def find_pairs(lst: list[int], target: int) -> list[tuple[int, int]]:
    pairs = []
    for i in range(len(lst)):
        for j in range(i + 1, len(lst)):
            if lst[i] + lst[j] == target:
                pairs.append((lst[i], lst[j]))
    return pairs
```

